CREATE DEFINER=`ceo_usman`@`202.47.35.3` PROCEDURE `sp_add_currency_to_tenant` (IN `p_tenant_id` BIGINT, IN `p_currency_id` BIGINT, IN `p_is_base_currency` BOOLEAN, IN `p_created_by` BIGINT)   BEGIN
    DECLARE existing_base_count INT;
    
    -- Check if there's already a base currency
    IF p_is_base_currency = TRUE THEN
        SELECT COUNT(*) INTO existing_base_count 
        FROM tenant_currencies 
        WHERE tenant_id = p_tenant_id AND is_base_currency = TRUE;
        
        IF existing_base_count > 0 THEN
            -- Unset existing base currency
            UPDATE tenant_currencies 
            SET is_base_currency = FALSE 
            WHERE tenant_id = p_tenant_id AND is_base_currency = TRUE;
        END IF;
    END IF;
    
    -- Insert or update the currency mapping
        tenant_id,
        currency_id,
        is_base_currency,
        created_by
    ) VALUES (
        p_tenant_id,
        p_currency_id,
        COALESCE(p_is_base_currency, FALSE),
        p_created_by
    )
    ON DUPLICATE KEY UPDATE
        is_base_currency = VALUES(is_base_currency),
        updated_at = CURRENT_TIMESTAMP;
    
    -- Return success
    SELECT 1 AS success;
END$$

CREATE DEFINER=`ceo_usman`@`202.47.35.3` PROCEDURE `sp_create_currency` (IN `p_tenant_id` BIGINT, IN `p_currency_name` VARCHAR(100), IN `p_currency_symbol` VARCHAR(10), IN `p_currency_code` VARCHAR(3), IN `p_decimal_places` INT, IN `p_is_base_currency` BOOLEAN, IN `p_exchange_rate` DECIMAL(15,6), IN `p_created_by` BIGINT)   BEGIN
    DECLARE new_id BIGINT;
    DECLARE existing_base_count INT;
    
    -- Generate new ID
    SELECT COALESCE(MAX(id), 0) + 1 INTO new_id FROM currency_setup WHERE tenant_id = p_tenant_id;
    
    -- Check if there's already a base currency
    IF p_is_base_currency = TRUE THEN
        SELECT COUNT(*) INTO existing_base_count 
        FROM currency_setup 
        WHERE tenant_id = p_tenant_id AND is_base_currency = TRUE;
        
        IF existing_base_count > 0 THEN
            -- Unset existing base currency
            UPDATE currency_setup 
            SET is_base_currency = FALSE 
            WHERE tenant_id = p_tenant_id AND is_base_currency = TRUE;
        END IF;
    END IF;
    
    -- Insert the new currency
        id,
        tenant_id,
        currency_name,
        currency_symbol,
        currency_code,
        decimal_places,
        is_base_currency,
        exchange_rate,
        created_by,
        updated_by
    ) VALUES (
        new_id,
        p_tenant_id,
        p_currency_name,
        p_currency_symbol,
        p_currency_code,
        COALESCE(p_decimal_places, 2),
        COALESCE(p_is_base_currency, FALSE),
        COALESCE(p_exchange_rate, 1.000000),
        p_created_by,
        p_created_by
    );
    
    -- Return the new currency ID
    SELECT new_id AS currency_id;
END$$

CREATE DEFINER=`ceo_usman`@`202.47.35.3` PROCEDURE `sp_create_customer` (IN `p_tenant_id` BIGINT, IN `p_customer_code` VARCHAR(20), IN `p_customer_name` VARCHAR(255), IN `p_address` TEXT, IN `p_primary_phone` VARCHAR(15), IN `p_secondary_phone` VARCHAR(15), IN `p_identity_card_no` VARCHAR(15), IN `p_email` VARCHAR(300), IN `p_opening_debit_amount` DECIMAL(15,2), IN `p_opening_credit_amount` DECIMAL(15,2), IN `p_is_blacklisted` BOOLEAN, IN `p_created_by` BIGINT)   BEGIN
