-- Table structure for table `vehicle_registrations`
--

CREATE TABLE `vehicle_registrations` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `tenant_id` bigint(20) UNSIGNED NOT NULL,
  `application_no` varchar(50) NOT NULL COMMENT 'Unique application number e.g., VR-0001',
  `application_date` date NOT NULL,
  `registration_no` varchar(50) DEFAULT NULL COMMENT 'Final registration number (filled after approval)',
  `registration_type` varchar(100) NOT NULL COMMENT 'New Registration / Transfer / Renewal',
  `registration_city` varchar(100) NOT NULL COMMENT 'City where registration is being done',
  `reg_status` varchar(50) NOT NULL DEFAULT 'Pending' COMMENT 'Pending, Submitted, In Process, Completed, Delivered, Cancelled',
  `customer_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Foreign key to customers table',
  `customer_name` varchar(255) NOT NULL,
  `phone_number` varchar(20) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `cnic_no` varchar(50) DEFAULT NULL COMMENT 'Customer National ID Number',
  `invoice_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Link to original sale invoice',
  `invoice_number` varchar(50) DEFAULT NULL,
  `sale_date` date DEFAULT NULL,
  `product_name` varchar(255) NOT NULL COMMENT 'Vehicle model name e.g., Honda CD 70',
  `engine_cc` varchar(50) DEFAULT NULL COMMENT 'Engine capacity e.g., 70cc, 125cc',
  `chassis_no` varchar(100) DEFAULT NULL COMMENT 'Vehicle chassis number',
  `motor_no` varchar(100) DEFAULT NULL COMMENT 'Vehicle motor/engine number',
  `colour` varchar(50) DEFAULT NULL,
  `model_year` varchar(20) DEFAULT NULL COMMENT 'Manufacturing year',
  `registration_fee` decimal(10,2) NOT NULL DEFAULT 0.00,
  `number_plate_fee` decimal(10,2) NOT NULL DEFAULT 0.00,
  `smart_card_fee` decimal(10,2) NOT NULL DEFAULT 0.00,
  `service_charges` decimal(10,2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'Sum of all fees',
  `payment_method` varchar(50) DEFAULT NULL COMMENT 'cash / bank_transfer / cheque / online',
  `bank_account_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Link to bank accounts table',
  `amount_paid` decimal(10,2) NOT NULL DEFAULT 0.00,
  `remaining_balance` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'Total - Paid',
  `expected_delivery_date` date DEFAULT NULL,
  `submitted_date` date DEFAULT NULL COMMENT 'Date submitted to excise/authority',
  `completed_date` date DEFAULT NULL COMMENT 'Date registration was completed',
  `remarks` text DEFAULT NULL COMMENT 'Status remarks/notes from authority',
  `delivery_date` date DEFAULT NULL,
  `delivered_to` varchar(255) DEFAULT NULL COMMENT 'Name of person who received',
  `delivered_by` varchar(255) DEFAULT NULL COMMENT 'Staff member who delivered',
  `delivery_notes` text DEFAULT NULL,
  `notes` text DEFAULT NULL COMMENT 'Internal notes',
  `created_by` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'User who created the record',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'User who last updated the record',
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Vehicle Registration Applications';

